// =====================================================================
//  model_rom.v  --  the stored models, in their own 32 x 32 x 24 space
//
//  GENERATED FILE -- do not hand edit.  Made by _diag/gen_walk.py.
//
//  ---------------------------------------------------------------------
//  LAYOUT
//  ---------------------------------------------------------------------
//      m[   0 .. 1023]     the chicken, one frame
//      m[1024 .. 7935]     walking figure, frames 0..8   (768 each)
//
//      dna_a[0 .. 767]     DNA backbone 1  -> red
//      dna_b[0 .. 767]     DNA backbone 2  -> blue
//      dna_r[0 .. 767]     DNA rungs       -> white
//
//  A frame base is 768*f = (f<<9)+(f<<8), so no multiplier.
//  The DNA is ONE frame: gen_dna.py only rotates the helix about its
//  own axis, and the display already turns the volume past the eye,
//  so animating it as well spun it twice and cost eight frames.
//  Three masks instead of one let each backbone have its own colour,
//  which a z -> colour table could never do.
//
//  colz[{sel[1:0], z[4:0]}] : 0 chicken, 1 walker.
//
//  ---------------------------------------------------------------------
//  SIX STAGES, ONE VOXEL PER CLOCK
//  ---------------------------------------------------------------------
//  torus_pattern is six clocks deep and vol_fill expects every pattern
//  to match, so the last two stages only pad.  Changing this depth
//  means changing vol_fill's LAT as well.
// =====================================================================

module model_rom (
    input  wire        clk,

    input  wire [6:0]  x,
    input  wire [6:0]  y,
    input  wire [5:0]  z,

    input  wire [1:0]  sel,       // 0 chicken, 1 walker, 2 DNA
    input  wire [3:0]  fr,        // which frame, 0 .. 8 (DNA ignores it)

    output reg  [2:0]  rgb        // {r, g, b}, valid 6 clocks after x/y/z
);

    // ==================================================================
    //  stage 1 : back into the model's own 32 x 32 x 24 space
    // ==================================================================
    wire signed [11:0] dxm = {3'b000, x} - 12'sd64;
    wire signed [11:0] dym = {3'b000, y} - 12'sd64;
    wire signed [11:0] dzm = {3'b000, z} - 12'sd32;

    wire signed [11:0] xs = ((dxm * 12'sd3) >>> 3) + 12'sd16;
    wire signed [11:0] ys = ((dym * 12'sd3) >>> 3) + 12'sd16;
    wire signed [11:0] zs = ((dzm * 12'sd3) >>> 3) + 12'sd12;

    // x, y and z are all tested.  Without the y and z tests the 5 bit
    // index wraps, and a mirrored copy of the model is painted round
    // the rim of the volume.
    wire ok = (xs >= 12'sd0) && (xs <= 12'sd31) &&
              (ys >= 12'sd0) && (ys <= 12'sd31) &&
              (zs >= 12'sd0) && (zs <= 12'sd23);

    reg [4:0] q1_xs, q1_ys, q1_zs;
    reg [3:0] q1_fr;
    reg [1:0] q1_sel;
    reg       q1_ok;

    initial begin
        q1_xs = 5'd0; q1_ys = 5'd0; q1_zs = 5'd0;
        q1_fr = 4'd0; q1_sel = 2'd0; q1_ok = 1'b0;
    end

    always @(posedge clk) begin
        q1_xs  <= xs[4:0];
        q1_ys  <= ys[4:0];
        q1_zs  <= zs[4:0];
        q1_fr  <= fr;
        q1_sel <= sel;
        q1_ok  <= ok;
    end

    // ==================================================================
    //  stage 2 : the memory addresses
    // ==================================================================
    wire [12:0] wrow = {3'b000, q1_zs, q1_ys};
    wire [12:0] wfrm = {q1_fr, 9'b0} + {q1_fr, 8'b0};
    wire [12:0] wbas = (q1_sel == 2'd1) ? (13'd1024 + wfrm) : 13'd0;

    reg [12:0] q2_addr, q2_dadr;
    reg [4:0]  q2_xs, q2_zs;
    reg [1:0]  q2_sel;
    reg        q2_ok;

    initial begin
        q2_addr = 13'd0; q2_dadr = 13'd0;
        q2_xs = 5'd0; q2_zs = 5'd0; q2_sel = 2'd0; q2_ok = 1'b0;
    end

    always @(posedge clk) begin
        q2_addr <= wbas + wrow;
        q2_dadr <= {3'b000, q1_zs, q1_ys};
        q2_xs   <= q1_xs;
        q2_zs   <= q1_zs;
        q2_sel  <= q1_sel;
        q2_ok   <= q1_ok;
    end

    // ==================================================================
    //  stage 3 : the memories answer, one clock later
    // ==================================================================
    reg [31:0] q3_word, q3_da, q3_db, q3_dr;
    reg [4:0]  q3_xs, q3_zs;
    reg [1:0]  q3_sel;
    reg        q3_ok;

    initial begin
        q3_word = 32'd0; q3_da = 32'd0; q3_db = 32'd0; q3_dr = 32'd0;
        q3_xs = 5'd0; q3_zs = 5'd0; q3_sel = 2'd0; q3_ok = 1'b0;
    end

    always @(posedge clk) begin
        q3_word <= m[q2_addr];
        q3_da   <= dna_a[q2_dadr];
        q3_db   <= dna_b[q2_dadr];
        q3_dr   <= dna_r[q2_dadr];
        q3_xs   <= q2_xs;
        q3_zs   <= q2_zs;
        q3_sel  <= q2_sel;
        q3_ok   <= q2_ok;
    end

    // ==================================================================
    //  stage 4 : pick the voxel out of the row, and colour it
    // ==================================================================
    reg [2:0] q4_rgb;

    initial q4_rgb = 3'd0;

    always @(posedge clk) begin
        if (q3_sel == 2'd2) begin
            q4_rgb <= !q3_ok        ? 3'b000 :
                      q3_dr[q3_xs]  ? 3'b111 :      // rung   : white
                      q3_da[q3_xs]  ? 3'b100 :      // chain 1: red
                      q3_db[q3_xs]  ? 3'b001 :      // chain 2: blue
                                      3'b000;
        end else begin
            q4_rgb <= (q3_ok && q3_word[q3_xs]) ? colz[{q3_sel, q3_zs}]
                                                : 3'b000;
        end
    end

    // ==================================================================
    //  stages 5 and 6 : padding, so the latency matches torus_pattern
    // ==================================================================
    reg [2:0] q5_rgb;

    initial begin
        q5_rgb = 3'd0;
        rgb    = 3'd0;
    end

    always @(posedge clk) begin
        q5_rgb <= q4_rgb;
        rgb    <= q5_rgb;
    end

